-- List Manager example: Recipe Collection
-- Run this file in phpMyAdmin (or the mysql client) on your Joomla database, then import the
-- configuration file in Components > List Manager > Import. The table name has no Joomla prefix.
DROP TABLE IF EXISTS `lm_recipes`;
CREATE TABLE `lm_recipes` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(120) NOT NULL,
  `category` varchar(20) NOT NULL,
  `difficulty` varchar(10) NOT NULL DEFAULT 'Easy',
  `prep_min` smallint(6) NOT NULL DEFAULT 0,
  `cook_min` smallint(6) NOT NULL DEFAULT 0,
  `total_min` smallint(6) NOT NULL DEFAULT 0,
  `servings` tinyint(4) NOT NULL DEFAULT 4,
  `calories` smallint(6) NOT NULL DEFAULT 0,
  `description` varchar(255) DEFAULT NULL,
  `ingredients` text,
  `method` text,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

