INSERT INTO `lm_recipes` (`name`, `category`, `difficulty`, `prep_min`, `cook_min`, `total_min`, `servings`, `calories`, `description`, `ingredients`, `method`) VALUES
('Tomato Bruschetta', 'Starter', 'Easy', 10, 5, 15, 4, 180, 'Toasted rustic bread piled with ripe tomatoes, garlic and basil.', '8 slices ciabatta\n4 ripe tomatoes, diced\n2 garlic cloves\n1 handful fresh basil\n3 tbsp olive oil\nSea salt and black pepper', '1. Toast the bread until golden on both sides.\n2. Rub each slice with a halved garlic clove.\n3. Toss the tomatoes with oil, basil, salt and pepper.\n4. Spoon over the toast and serve at once.'),
('Garlic Prawns', 'Starter', 'Medium', 10, 8, 18, 4, 240, 'Sizzling prawns in garlic, chilli and olive oil, with bread for mopping up.', '500 g raw king prawns, peeled\n5 garlic cloves, sliced\n1 red chilli, sliced\n120 ml olive oil\nJuice of 1 lemon\nChopped parsley', '1. Heat the oil gently with the garlic and chilli for 2 minutes.\n2. Raise the heat and add the prawns.\n3. Cook 2-3 minutes per side until pink.\n4. Finish with lemon juice and parsley.'),
('Stuffed Mushrooms', 'Starter', 'Easy', 15, 20, 35, 4, 160, 'Button mushrooms filled with herbs, breadcrumbs and Parmesan.', '16 large button mushrooms\n60 g breadcrumbs\n40 g grated Parmesan\n2 garlic cloves, minced\n2 tbsp chopped parsley\n2 tbsp olive oil', '1. Heat the oven to 200 C.\n2. Remove the stalks and chop them finely.\n3. Mix the stalks with breadcrumbs, Parmesan, garlic, parsley and oil.\n4. Fill the caps and bake for 20 minutes.'),
('Beef Carpaccio', 'Starter', 'Medium', 20, 0, 20, 4, 210, 'Paper-thin raw beef with rocket, capers and shaved Parmesan.', '300 g beef fillet, well chilled\n2 handfuls rocket\n40 g Parmesan shavings\n2 tbsp capers\nJuice of 1 lemon\n4 tbsp extra virgin olive oil', '1. Freeze the beef for 30 minutes so it slices cleanly.\n2. Slice as thinly as possible and arrange on plates.\n3. Scatter rocket, capers and Parmesan.\n4. Dress with lemon juice, oil and pepper.'),
('Chicken Tikka Masala', 'Main', 'Medium', 25, 35, 60, 4, 520, 'Marinated chicken in a creamy, mildly spiced tomato sauce.', '700 g chicken thigh, cubed\n150 g natural yoghurt\n2 tbsp tikka masala paste\n1 onion, chopped\n400 g tinned tomatoes\n100 ml single cream\nFresh coriander', '1. Marinate the chicken in yoghurt and half the paste for 30 minutes.\n2. Grill or pan-fry until charred.\n3. Soften the onion, add the remaining paste and tomatoes and simmer 15 minutes.\n4. Add the chicken and cream, simmer 10 minutes and top with coriander.'),
('Beef Bourguignon', 'Main', 'Hard', 30, 180, 210, 6, 610, 'Beef slowly braised in red wine with bacon, mushrooms and pearl onions.', '1 kg braising beef, cubed\n750 ml red Burgundy\n150 g smoked bacon\n250 g mushrooms\n12 pearl onions\n2 carrots\n2 tbsp tomato purée\nThyme and bay', '1. Brown the beef in batches and set aside.\n2. Fry the bacon, carrots and onions, then stir in the tomato purée.\n3. Return the beef, add wine, thyme and bay and cover.\n4. Braise at 160 C for 2.5 hours, adding the mushrooms for the last 30 minutes.'),
('Spaghetti Carbonara', 'Main', 'Easy', 10, 15, 25, 2, 720, 'The Roman classic: eggs, pecorino, guanciale and black pepper. No cream.', '200 g spaghetti\n100 g guanciale or pancetta\n2 whole eggs + 1 yolk\n50 g pecorino, grated\nFreshly ground black pepper', '1. Fry the guanciale until crisp and the fat has rendered.\n2. Boil the spaghetti in salted water until al dente.\n3. Whisk the eggs with the pecorino and plenty of pepper.\n4. Toss the hot pasta with the guanciale, then off the heat stir in the egg mixture with a splash of pasta water.'),
('Lemon Baked Salmon', 'Main', 'Easy', 10, 18, 28, 2, 430, 'Oven-baked salmon fillets with lemon, dill and new potatoes.', '2 salmon fillets\n1 lemon, sliced\n300 g new potatoes\n2 tbsp olive oil\nFresh dill\nSalt and pepper', '1. Roast the halved potatoes for 15 minutes at 200 C.\n2. Place the salmon on the tray, top with lemon slices and oil.\n3. Bake for 15-18 minutes until just cooked through.\n4. Sprinkle with dill and serve.'),
('Mushroom Risotto', 'Main', 'Medium', 10, 30, 40, 4, 480, 'Creamy arborio rice with mixed mushrooms, white wine and Parmesan.', '320 g arborio rice\n300 g mixed mushrooms\n1 litre hot vegetable stock\n1 onion, finely chopped\n100 ml white wine\n50 g Parmesan\n30 g butter', '1. Fry the mushrooms until golden, then set aside.\n2. Soften the onion, add the rice and toast for 2 minutes.\n3. Add the wine, then the stock a ladle at a time, stirring, for about 20 minutes.\n4. Fold in the mushrooms, butter and Parmesan and rest for 2 minutes.'),
('Classic Tiramisu', 'Dessert', 'Medium', 30, 0, 30, 8, 390, 'Espresso-soaked sponge fingers layered with mascarpone cream and cocoa.', '500 g mascarpone\n4 eggs, separated\n100 g caster sugar\n300 ml strong espresso, cooled\n24 sponge fingers\nCocoa powder', '1. Beat the yolks with the sugar, then fold in the mascarpone.\n2. Whisk the whites to stiff peaks and fold them in.\n3. Dip the sponge fingers briefly in the coffee and layer with the cream.\n4. Chill for at least 6 hours and dust with cocoa.'),
('Crème Brûlée', 'Dessert', 'Hard', 20, 45, 65, 6, 340, 'Silky vanilla custard under a thin, crackling layer of caramel.', '500 ml double cream\n1 vanilla pod\n5 egg yolks\n90 g caster sugar\nExtra sugar for the top', '1. Warm the cream with the vanilla seeds.\n2. Whisk the yolks and sugar, then stream in the cream.\n3. Pour into ramekins and bake in a water bath at 150 C for 40 minutes.\n4. Chill, sprinkle with sugar and caramelise with a blowtorch.'),
('Vanilla Panna Cotta', 'Dessert', 'Medium', 15, 5, 20, 6, 310, 'A trembling Italian cream set with gelatine, served with berry coulis.', '400 ml double cream\n200 ml whole milk\n60 g sugar\n3 gelatine leaves\n1 tsp vanilla paste\n200 g raspberries', '1. Soak the gelatine in cold water.\n2. Heat cream, milk, sugar and vanilla until steaming.\n3. Squeeze the gelatine and stir into the cream.\n4. Pour into moulds, chill for 4 hours and serve with crushed raspberries.'),
('Chocolate Mousse', 'Dessert', 'Easy', 20, 0, 20, 6, 300, 'Light, airy dark chocolate mousse with just three ingredients.', '200 g dark chocolate, 70%\n4 eggs, separated\n2 tbsp caster sugar\nPinch of salt', '1. Melt the chocolate and let it cool slightly.\n2. Stir in the yolks.\n3. Whisk the whites with the salt and sugar to soft peaks.\n4. Fold gently into the chocolate and chill for 3 hours.'),
('Chickpea Curry', 'Vegan', 'Easy', 10, 25, 35, 4, 380, 'A fragrant one-pot curry of chickpeas, spinach and coconut milk.', '2 tins chickpeas, drained\n400 ml coconut milk\n400 g tinned tomatoes\n1 onion, chopped\n3 tbsp curry paste\n200 g baby spinach\nBasmati rice to serve', '1. Soften the onion, then fry the curry paste for 1 minute.\n2. Add tomatoes, coconut milk and chickpeas.\n3. Simmer for 20 minutes.\n4. Stir in the spinach until wilted and serve with rice.'),
('Lentil Bolognese', 'Vegan', 'Medium', 15, 40, 55, 4, 420, 'A hearty ragù of green lentils, carrots and red wine over spaghetti.', '250 g green lentils\n1 onion, 2 carrots, 2 celery sticks\n400 g tinned tomatoes\n100 ml red wine\n2 tbsp tomato purée\n320 g spaghetti', '1. Sweat the chopped vegetables for 10 minutes.\n2. Add the purée, wine, tomatoes, lentils and 500 ml water.\n3. Simmer 30 minutes until thick.\n4. Serve over spaghetti.'),
('Rainbow Buddha Bowl', 'Vegan', 'Easy', 20, 25, 45, 2, 460, 'Quinoa, roasted sweet potato, avocado and tahini dressing.', '150 g quinoa\n1 sweet potato, cubed\n1 avocado\n100 g red cabbage, shredded\n1 tin chickpeas\n2 tbsp tahini\nJuice of 1 lemon', '1. Roast the sweet potato and chickpeas for 25 minutes at 200 C.\n2. Cook the quinoa in salted water.\n3. Whisk tahini, lemon and water into a pourable dressing.\n4. Assemble the bowls and drizzle.'),
('Vegan Pad Thai', 'Vegan', 'Medium', 20, 12, 32, 4, 510, 'Rice noodles tossed with tofu, peanuts and a sweet-sour tamarind sauce.', '250 g flat rice noodles\n200 g firm tofu, cubed\n3 tbsp tamarind paste\n2 tbsp soy sauce\n1 tbsp palm sugar\n100 g bean sprouts\n50 g roasted peanuts\n1 lime', '1. Soak the noodles in hot water until pliable.\n2. Fry the tofu until golden.\n3. Add noodles and the sauce of tamarind, soy and sugar; toss for 3 minutes.\n4. Add bean sprouts, top with peanuts and serve with lime.'),
('Sourdough Loaf', 'Baking', 'Hard', 30, 45, 75, 10, 190, 'A crusty country loaf with an open crumb; needs an overnight rise.', '500 g strong white flour\n350 g water\n100 g active sourdough starter\n10 g salt', '1. Mix the flour and water and rest for 1 hour.\n2. Add the starter and salt and fold every 30 minutes for 3 hours.\n3. Shape, then prove overnight in the fridge.\n4. Bake in a hot Dutch oven at 240 C: 20 minutes lid on, 25 minutes lid off.'),
('Blueberry Muffins', 'Baking', 'Easy', 15, 22, 37, 12, 260, 'Tender bakery-style muffins bursting with blueberries.', '280 g plain flour\n150 g sugar\n2 tsp baking powder\n2 eggs\n240 ml milk\n90 g melted butter\n200 g blueberries', '1. Mix the dry ingredients in one bowl and the wet in another.\n2. Combine briefly and fold in the blueberries.\n3. Divide between 12 cases.\n4. Bake at 200 C for 20-22 minutes.'),
('Cinnamon Rolls', 'Baking', 'Hard', 40, 25, 65, 12, 340, 'Soft yeasted rolls swirled with cinnamon sugar and cream cheese icing.', '500 g strong flour\n7 g dried yeast\n250 ml warm milk\n80 g butter\n100 g brown sugar\n2 tbsp cinnamon\n150 g cream cheese icing', '1. Make a soft dough and prove for 1 hour.\n2. Roll out, spread with butter, sugar and cinnamon and roll up.\n3. Cut into 12 and prove again for 40 minutes.\n4. Bake at 180 C for 25 minutes and ice while warm.'),
('Banana Bread', 'Baking', 'Easy', 15, 55, 70, 10, 280, 'Moist loaf made with very ripe bananas and a hint of nutmeg.', '3 ripe bananas\n200 g plain flour\n120 g sugar\n80 g melted butter\n1 egg\n1 tsp baking soda\nPinch of nutmeg', '1. Mash the bananas and mix in butter, sugar and egg.\n2. Fold in the flour, soda and nutmeg.\n3. Pour into a lined loaf tin.\n4. Bake at 175 C for 55 minutes.'),
('Tomato Basil Soup', 'Soup', 'Easy', 10, 30, 40, 4, 190, 'Velvety roasted tomato soup with fresh basil.', '1 kg ripe tomatoes\n1 onion\n3 garlic cloves\n500 ml vegetable stock\nHandful basil\n2 tbsp olive oil', '1. Roast the tomatoes, onion and garlic with oil for 25 minutes at 200 C.\n2. Tip into a pan with the stock and simmer 5 minutes.\n3. Add the basil and blend until smooth.\n4. Season and serve hot.'),
('French Onion Soup', 'Soup', 'Medium', 15, 60, 75, 4, 420, 'Deeply caramelised onions in beef broth under a cheesy croûte.', '1 kg onions, sliced\n50 g butter\n1 litre beef stock\n150 ml white wine\n4 slices baguette\n120 g Gruyère, grated', '1. Cook the onions slowly in butter for 40 minutes until deep brown.\n2. Add the wine, then the stock, and simmer 15 minutes.\n3. Ladle into ovenproof bowls and top with baguette and Gruyère.\n4. Grill until bubbling.'),
('Chicken Noodle Soup', 'Soup', 'Easy', 15, 40, 55, 6, 310, 'Comforting broth with tender chicken, carrots and egg noodles.', '2 chicken breasts\n1.5 litres chicken stock\n2 carrots, 2 celery sticks\n1 onion\n150 g egg noodles\nFresh parsley', '1. Simmer the chicken in the stock with the vegetables for 25 minutes.\n2. Lift out and shred the chicken.\n3. Add the noodles and cook for 6 minutes.\n4. Return the chicken and finish with parsley.'),
('Andalusian Gazpacho', 'Soup', 'Easy', 15, 0, 15, 4, 150, 'Chilled Spanish tomato and cucumber soup, ready with no cooking.', '1 kg ripe tomatoes\n1 cucumber\n1 green pepper\n1 garlic clove\n3 tbsp sherry vinegar\n80 ml olive oil\nSalt', '1. Roughly chop all the vegetables.\n2. Blend with the vinegar, oil and salt until very smooth.\n3. Strain if you like and chill for 2 hours.\n4. Serve cold with a drizzle of olive oil.');
